<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
 post_only();$action=$_POST['action']??'';$id=(int)($_POST['id_admin']??0);
 if($action==='delete'){$count=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='Admin'")->fetchColumn();if($id===(int)$_SESSION['user_id'])flash('error','No puedes eliminar la cuenta con la que has iniciado sesión.');elseif($count<=1)flash('error','Debe existir al menos un administrador.');else{$pdo->prepare("DELETE FROM usuarios WHERE id_usuario=? AND rol='Admin'")->execute([$id]);flash('success','Administrador eliminado.');}}
 elseif($action==='create'||$action==='edit'){$nombre=trim($_POST['nombre']??'');$documento=trim($_POST['documento']??'');$correo=strtolower(trim($_POST['correo']??''));$password=$_POST['password']??'';if($nombre===''||mb_strlen($nombre)>100||$documento===''||mb_strlen($documento)>30||!filter_var($correo,FILTER_VALIDATE_EMAIL)||mb_strlen($correo)>150){flash('error','Ingresa nombre, documento y correo válidos.');}elseif($action==='create'&&strlen($password)<8){flash('error','La contraseña debe tener al menos 8 caracteres.');}elseif($action==='edit'&&$password!==''&&strlen($password)<8){flash('error','La nueva contraseña debe tener al menos 8 caracteres.');}else{try{if($action==='create'){$pdo->prepare("INSERT INTO usuarios(nombre,documento,correo,password_hash,rol) VALUES(?,?,?,?, 'Admin')")->execute([$nombre,$documento,$correo,password_hash($password,PASSWORD_DEFAULT)]);flash('success','Administrador creado.');}else{$check=$pdo->prepare("SELECT id_usuario FROM usuarios WHERE id_usuario=? AND rol='Admin'");$check->execute([$id]);if(!$check->fetch())throw new RuntimeException('El administrador no existe.');if($password!=='')$pdo->prepare("UPDATE usuarios SET nombre=?,documento=?,correo=?,password_hash=? WHERE id_usuario=? AND rol='Admin'")->execute([$nombre,$documento,$correo,password_hash($password,PASSWORD_DEFAULT),$id]);else $pdo->prepare("UPDATE usuarios SET nombre=?,documento=?,correo=? WHERE id_usuario=? AND rol='Admin'")->execute([$nombre,$documento,$correo,$id]);if($id===(int)$_SESSION['user_id'])$_SESSION['user_name']=$nombre;flash('success','Administrador actualizado.');}}catch(Throwable $ex){flash('error',$ex instanceof RuntimeException?$ex->getMessage():($ex->getCode()==='23000'?'El documento o correo ya está registrado.':'No se pudo guardar el administrador.'));}}}
 header('Location: admins.php');exit;
}
$admins=$pdo->query("SELECT id_usuario,nombre,documento,correo,creado_en FROM usuarios WHERE rol='Admin' ORDER BY id_usuario")->fetchAll();$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare("SELECT id_usuario,nombre,documento,correo FROM usuarios WHERE id_usuario=? AND rol='Admin'");$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}page_start('Administradores','admins.php');
?>
<div class="page-heading"><div><span class="eyebrow">ROLES</span><h1>Administradores</h1><p>Las cuentas se almacenan en usuarios y se distinguen con el rol Admin.</p></div></div>
<section class="panel mb-4"><h2><?= $edit?'Editar administrador':'Crear administrador'; ?></h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="<?= $edit?'edit':'create'; ?>"><?php if($edit): ?><input type="hidden" name="id_admin" value="<?= (int)$edit['id_usuario']; ?>"><?php endif; ?><div class="col-md-3"><label class="form-label">Nombre</label><input class="form-control" name="nombre" maxlength="100" required value="<?= e($edit['nombre']??''); ?>"></div><div class="col-md-3"><label class="form-label">Documento</label><input class="form-control" name="documento" maxlength="30" required value="<?= e($edit['documento']??''); ?>"></div><div class="col-md-3"><label class="form-label">Correo</label><input class="form-control" type="email" name="correo" maxlength="150" required value="<?= e($edit['correo']??''); ?>"></div><div class="col-md-3"><label class="form-label"><?= $edit?'Nueva contraseña (opcional)':'Contraseña'; ?></label><input class="form-control" type="password" name="password" minlength="8" <?= $edit?'':'required'; ?> autocomplete="new-password"></div><div class="col-12"><button class="btn btn-primary">Guardar</button><?php if($edit): ?> <a class="btn btn-outline-secondary" href="admins.php">Cancelar</a><?php endif; ?></div></form></section>
<section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Documento</th><th>Correo</th><th>Rol</th><th>Acciones</th></tr></thead><tbody><?php foreach($admins as $a): ?><tr><td><?= e($a['nombre']); ?> <?= (int)$a['id_usuario']===(int)$_SESSION['user_id']?'<span class="badge text-bg-primary">Tú</span>':''; ?></td><td><?= e($a['documento']); ?></td><td><?= e($a['correo']); ?></td><td><span class="badge text-bg-dark">Admin</span></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="admins.php?editar=<?= (int)$a['id_usuario']; ?>">Editar</a><?php if((int)$a['id_usuario']!==(int)$_SESSION['user_id']): ?><form method="post" onsubmit="return confirm('¿Eliminar este administrador?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_admin" value="<?= (int)$a['id_usuario']; ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_end(); ?>
